#!/usr/bin/env bash
#
# build-fixtures.sh — build every dsh-jujutsu test fixture repository.
#
#   usage:  test/fixtures/build-fixtures.sh [ROOT]
#           ROOT defaults to /tmp/dsh-jujutsu-fixtures
#
# Idempotent: ROOT is deleted and rebuilt from scratch on every run. The script
# verifies the shape of every fixture it builds and exits non-zero if any check
# fails, so a green run means the fixtures are usable.
#
# Requires: jj >= 0.46 and git on PATH. jj-hunk is optional; when present it is
# used for one smoke check on jj-with-changes.
#
# The user's real jj configuration is never read: JJ_CONFIG is pinned to
# /dev/null plus a generated identity file inside ROOT. Nothing is written
# outside ROOT.

set -euo pipefail

ROOT="${1:-/tmp/dsh-jujutsu-fixtures}"

case "$ROOT" in
  "" | "/" | "." | "..")
    echo "refusing to build fixtures at ROOT='$ROOT'" >&2
    exit 2
    ;;
esac

for tool in jj git; do
  command -v "$tool" >/dev/null 2>&1 || { echo "$tool not found on PATH" >&2; exit 2; }
done

# --------------------------------------------------------------- root + config

rm -rf -- "$ROOT"
mkdir -p -- "$ROOT"
ROOT="$(cd -- "$ROOT" && pwd)"

JJ_IDENTITY="$ROOT/jj-config.toml"
cat > "$JJ_IDENTITY" <<'TOML'
# Generated by test/fixtures/build-fixtures.sh.
# Lives outside every fixture repo on purpose: a config file written into a
# working copy becomes a working-copy change and perturbs jj-hunk's hunk IDs.
[user]
name = "dsh-jujutsu fixture"
email = "fixture@example.invalid"
TOML

# /dev/null comes first, so the user's ~/.config/jj/config.toml is not read.
export JJ_CONFIG="/dev/null:$JJ_IDENTITY"

# ------------------------------------------------------------------- fixtures

# 1. plain-git — a normal Git repo with no .jj. The plugin must be invisible.
mkdir -p "$ROOT/plain-git"
cd "$ROOT/plain-git"
git init -q -b main
git config user.name "dsh-jujutsu fixture"
git config user.email "fixture@example.invalid"
git config commit.gpgsign false
printf '# plain git\n\nNot a Jujutsu workspace.\n' > README.md
git add README.md
git commit -q -m "initial commit"

# 2. not-a-repo — an empty directory.
mkdir -p "$ROOT/not-a-repo"

# 3. jj-native — jj git init --no-colocate: .jj only, no .git anywhere.
mkdir -p "$ROOT/jj-native"
cd "$ROOT/jj-native"
jj git init --no-colocate >/dev/null
printf '# jj native\n\nNon-colocated: there is no .git here.\n' > README.md
jj commit -m "initial commit" >/dev/null

# 4. jj-colocated — jj git init: both .jj/ and .git/.
mkdir -p "$ROOT/jj-colocated"
cd "$ROOT/jj-colocated"
jj git init >/dev/null
printf '# jj colocated\n\nBoth .jj/ and .git/ exist.\n' > README.md
jj commit -m "initial commit" >/dev/null

# 5. jj-secondary — a colocated repo plus `jj workspace add`. The secondary
#    workspace has .jj/ as a directory and .git as a *file* (a Git worktree).
mkdir -p "$ROOT/jj-secondary/primary"
cd "$ROOT/jj-secondary/primary"
jj git init >/dev/null
printf '# jj secondary primary\n' > README.md
jj commit -m "initial commit" >/dev/null
jj workspace add "$ROOT/jj-secondary/secondary" >/dev/null

# 6. jj-with-changes — a colocated repo whose single file carries two
#    independent one-line changes (a timeout and a log level), for jj-hunk.
mkdir -p "$ROOT/jj-with-changes"
cd "$ROOT/jj-with-changes"
jj git init >/dev/null
mkdir -p src
cat > src/server.js <<'JS'
const TIMEOUT_MS = 5000;
function request() {
  log.debug("request");
  return fetch("/api", { timeout: TIMEOUT_MS });
}
JS
jj commit -m "base" >/dev/null
cat > src/server.js <<'JS'
const TIMEOUT_MS = 30000;
function request() {
  log.info("request");
  return fetch("/api", { timeout: TIMEOUT_MS });
}
JS

# 7. jj-nested — a jj repo inside a subdirectory of another jj repo. The
#    nearest .jj/ (the inner one) is the workspace root for detection.
mkdir -p "$ROOT/jj-nested/outer"
cd "$ROOT/jj-nested/outer"
jj git init >/dev/null
printf '# jj nested outer\n' > README.md
jj commit -m "outer base" >/dev/null
mkdir -p sub
cd "$ROOT/jj-nested/outer/sub"
jj git init >/dev/null
printf 'inner\n' > inner.txt

# ------------------------------------------------------------------- verify

fail=0
ok()      { printf '  ok    %s\n' "$*"; }
bad()     { printf '  FAIL  %s\n' "$*" >&2; fail=1; }
want_dir()  { [ -d "$1" ] && ok "dir  ${1#"$ROOT"/}" || bad "missing directory $1"; }
want_file() { [ -f "$1" ] && ok "file ${1#"$ROOT"/}" || bad "missing file $1"; }
want_none() { [ ! -e "$1" ] && ok "absent ${1#"$ROOT"/}" || bad "unexpected $1"; }

echo "verifying fixtures under $ROOT"

# plain-git: .git yes, .jj no.
want_dir  "$ROOT/plain-git/.git"
want_none "$ROOT/plain-git/.jj"

# not-a-repo: completely empty.
if [ -z "$(ls -A "$ROOT/not-a-repo")" ]; then ok "not-a-repo is empty"; else bad "not-a-repo is not empty"; fi

# jj-native: .jj yes, .git no.
want_dir  "$ROOT/jj-native/.jj"
want_none "$ROOT/jj-native/.git"

# jj-colocated: both, as directories.
want_dir "$ROOT/jj-colocated/.jj"
want_dir "$ROOT/jj-colocated/.git"

# jj-secondary: primary colocated; secondary has .jj/ a dir and .git a file.
want_dir  "$ROOT/jj-secondary/primary/.jj"
want_dir  "$ROOT/jj-secondary/primary/.git"
want_dir  "$ROOT/jj-secondary/secondary/.jj"
want_file "$ROOT/jj-secondary/secondary/.git"

# jj-with-changes: two hunks in one file, one working-copy change.
want_dir "$ROOT/jj-with-changes/.jj"
want_dir "$ROOT/jj-with-changes/.git"
if command -v jj-hunk >/dev/null 2>&1; then
  hunks="$(cd "$ROOT/jj-with-changes" && jj-hunk list --format json | grep -c '"id":' || true)"
  if [ "$hunks" = "2" ]; then ok "jj-with-changes: jj-hunk lists 2 hunks"; else bad "jj-with-changes: expected 2 hunks, got $hunks"; fi
else
  printf '  skip  jj-hunk not on PATH; jj-with-changes hunk count unchecked\n'
fi

# jj-nested: both repos exist, and jj resolves the *inner* one as the root.
want_dir "$ROOT/jj-nested/outer/.jj"
want_dir "$ROOT/jj-nested/outer/.git"
want_dir "$ROOT/jj-nested/outer/sub/.jj"
inner_root="$(cd "$ROOT/jj-nested/outer/sub" && jj root)"
inner_real="$(cd "$ROOT/jj-nested/outer/sub" && pwd -P)"
if [ "$inner_root" = "$inner_real" ]; then
  ok "jj-nested: jj root inside sub/ is the inner repo"
else
  bad "jj-nested: jj root inside sub/ is '$inner_root', expected '$inner_real'"
fi

# ------------------------------------------------------------------- report

cat <<EOF

fixtures built under: $ROOT
jj config in use:    JJ_CONFIG=$JJ_CONFIG
  (export this in any shell that inspects the fixtures)

  plain-git        $ROOT/plain-git
  not-a-repo       $ROOT/not-a-repo
  jj-native        $ROOT/jj-native
  jj-colocated     $ROOT/jj-colocated
  jj-secondary     $ROOT/jj-secondary/primary  +  $ROOT/jj-secondary/secondary
  jj-with-changes  $ROOT/jj-with-changes
  jj-nested        $ROOT/jj-nested/outer  +  $ROOT/jj-nested/outer/sub
EOF

if [ "$fail" -ne 0 ]; then
  echo "fixture verification FAILED" >&2
  exit 1
fi
echo "all fixtures verified"
